import React from 'react';

export default function LmsDashboard({ username, onLogout }) {
  const cards = [
    { title: 'Total Students', value: '1,250' },
    { title: 'Total Teachers', value: '45' },
    { title: 'Active Classes', value: '120' },
    { title: 'Inactive Students', value: '25' }
  ];

  return (
    <div style={{ padding: '30px', backgroundColor: '#f8f9fa', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
        {cards.map((card, index) => (
          <div key={index} style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
            <p style={{ margin: '0', color: '#666', fontSize: '14px' }}>{card.title}</p>
            <h2 style={{ margin: '10px 0 0', color: '#333' }}>{card.value}</h2>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
        <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          <h3 style={{ marginBottom: '20px' }}>Enrollment Growth & Revenue</h3>
          <div style={{ height: '200px', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px dashed #ddd' }}>
            <p style={{ color: '#999' }}>Chart Area</p>
          </div>
        </div>

        <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          <h3 style={{ marginBottom: '20px' }}>Student Status</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {['Ruwan Name', 'John Name', 'Sama Name'].map((name, i) => (
              <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0', borderBottom: '1px solid #f0f0f0' }}>
                <span>{name}</span>
                <span style={{ backgroundColor: i === 1 ? '#d32f2f' : '#388e3c', color: '#fff', padding: '4px 10px', borderRadius: '4px', fontSize: '12px' }}>
                  {i === 1 ? 'Inactive' : 'Active'}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <button onClick={onLogout} style={{ marginTop: '30px', padding: '10px 20px', backgroundColor: '#d32f2f', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer' }}>
        Logout
      </button>
    </div>
  );
}
